          counts.ELSEIF++;
          var eifCond = inner.substring(7);
          if (eifCond.indexOf("==") === -1 && eifCond.indexOf("!=") === -1 && eifCond.indexOf("=") !== -1) {
            lint.singleEquals.push({ raw: raw, kind: "ELSEIF" });
          }
          var n2 = _extractCondName(eifCond);
          if (n2) { ifRefs[n2] = ifRefs[n2] || []; ifRefs[n2].push({ kind: "ELSEIF", raw: raw }); }
