          // is more accurate than just comparing counts because it
          // catches the right specific tags as broken.
          else lint.unmatchedEndif.push({ raw: raw });
        } else if (inner.indexOf("ELSE") === 0) {
          counts.ELSE++;
        } else if (inner.indexOf("TITLE:") === 0) {
