  // cascade (direct → quote/dash/NBSP-normalized → whitespace-flexible
  // → gap-tolerant) that handles Word's smart-quote auto-corrections,
  // NBSP, em-dash drift, and split-by-formatting issues.
  //
  // For tags longer than Word's 255-char search limit, we search for
  // a SHORTER signature substring (first ~120 chars after the opening
  // `{{`). Tags that long are rare but possible (long DEFs with many
  // options).
  function _findInDoc(rawText) {
    if (!rawText) return Promise.resolve(false);
    var needle = String(rawText);
    // Trim to Word's safe search length — 250 chars, well under the
    // documented 255 limit. Take a signature from the START so we
    // still find the right tag (tags are unique by their opening
    // segment in practice).
    if (needle.length > 250) needle = needle.slice(0, 250);
    return eli.host.runRaw("bd_template_tester:find_in_doc", function (context) {
      var body = context.document.body;
      // Prefer the kernel helper if present (apiVersion 2+). Falls
      // back to a 2-strategy local search if the helper isn't there.
      if (eli.host.helpers && typeof eli.host.helpers.searchWithFallback === "function") {
        return eli.host.helpers.searchWithFallback(body, needle, context).then(function (range) {
          if (!range) return false;
          range.select();
          return context.sync().then(function () { return true; });
        });
      }
      // Local fallback: try exact, then case-insensitive.
      var s1 = body.search(needle, { matchCase: true, matchWildcards: false });
      s1.load("items");
      return context.sync().then(function () {
        if (s1.items.length > 0) {
          s1.items[0].select();
          return context.sync().then(function () { return true; });
        }
        var s2 = body.search(needle, { matchCase: false, matchWildcards: false });
        s2.load("items");
        return context.sync().then(function () {
          if (s2.items.length > 0) {
            s2.items[0].select();
            return context.sync().then(function () { return true; });
          }
          return false;
        });
      });
    }).catch(function (err) {
      eli.log.event("tool", "bd_template_tester_find_in_doc_failed", { msg: err && err.message });
      return false;
    });
  }
  function _onFindInDoc(rawText) {
    _findInDoc(rawText).then(function (found) {
      if (found) _toast("🔎 Found in doc.", "ok");
      else _toast("Tag not found in doc — re-scan needed?", "warn");
    });
  }

  // Pull just the RHS value from an IF/ELSEIF tag for compact display
  // in the "Referenced by" pills. e.g. {{IF: PARTY_TYPE == Buyer}} → "Buyer".
  function _extractCondValueForDisplay(raw) {
    var inner = String(raw).replace(/^\{\{|\}\}$/g, "").trim();
    var afterColon = inner.replace(/^(IF|ELSEIF):\s*/i, "");
    var op = afterColon.indexOf("!=") !== -1 ? "!=" : (afterColon.indexOf("==") !== -1 ? "==" : null);
    if (!op) return afterColon.trim();
    var rhs = afterColon.split(op)[1] || "";
    return (op === "!=" ? "≠ " : "") + rhs.trim();
  }

  function _parseDefTag(raw) {
    if (!raw) return null;
    // Strip the outer {{ }} delimiters.
    var inner = String(raw).replace(/^\{\{|\}\}$/g, "");
    if (inner.indexOf("DEF:") !== 0) return null;
    // Mirror engine.js _parseLogicDefs format:
    //   DEF:NAME=defaultValue|opt1,opt2,opt3|warning
    // OR DEF:NAME|*placeholder|warning   (text-input form)
    var t = inner.substring(4).trim();
    var parts = t.split("|");
    var defPart    = (parts[0] || "").trim();
    var optionsPart = (parts[1] || "").trim();
    var warning    = parts.length > 2 ? parts.slice(2).join("|").trim() : null;
    var defSplit = defPart.split("=");
    var name = (defSplit[0] || "").trim();
