      if (_has(d.name)) return true;
      if (_has(d.raw)) return true;
      if (d.options && d.options.some(_has)) return true;
      // Match against referenced IFs too — useful when you remember an
      // option value but not the def name.
      if (d.references && d.references.some(function (r) { return _has(r.raw); })) return true;
      return false;
    });
