  function _paintScanResults(report) {
    var resEl = document.getElementById("_bdtt_scan_results");
    if (!resEl) return;
    if (Array.isArray(report)) report = { counts: null, defs: report, orphans: [], lint: null };
    // Apply the filter — counts at the TOP stay unfiltered (they're a
    // health summary of the whole doc, not the visible-rows list). Defs
    // and orphans and lint use the filtered slice.
