    var unfilteredOrphanCount = (report.orphans || []).length;
    var filtered = _filterReport(report, _bdttScanFilter);
    var counts = report.counts || {};
    var defs = filtered.defs || [];
    var orphans = filtered.orphans || [];
    var lint = filtered.lint || { singleEquals: [], missingColon: [], emptyDef: [], unmatchedIf: [], unmatchedEndif: [] };
    var totalTags = (counts.IF || 0) + (counts.ELSEIF || 0) + (counts.ELSE || 0) +
                    (counts.ENDIF || 0) + (counts.DEF || 0) + (counts.TITLE || 0) +
                    (counts.DELETE_LINE || 0) + (counts.ENTER || 0) + (counts.key || 0);
    if (!totalTags) {
