        hiddenLabel = '<div style="font-size:9px;color:#64748b;letter-spacing:0.04em;">' +
          'Showing <strong style="color:#0f172a;">' + defs.length + '</strong> of ' + unfilteredDefCount + ' DEF' + (unfilteredDefCount === 1 ? '' : 's') +
          (hiddenDefCount ? ' · ' + hiddenDefCount + ' hidden' : '') +
        '</div>';
