    // Merge spans (key + branch) into one sorted list for rendering.
    var keySpans = spans.filter(function (s) { return s.kind === "key"; });
    var allSpans = keySpans.concat(branchSpans);

    return {
      raw: output,
      paraSep: PARA_SEP,
      spans: allSpans,
      unsubbedSpans: unsubbedSpans,
      droppedAt: droppedAt,
      substitutionCount: substitutionCount,
      unsubbedCount: unsubbedSpans.length,
      droppedCount: Object.keys(droppedAt).reduce(function (n, k) { return n + droppedAt[k].length; }, 0),
      outputCharMeta: outputCharMeta,
      paraInfos: paraInfos,
    };
  }

  // Render the substitution result as escaped HTML with inline span
  // wrappers for highlighting + ⊘N drop chips.
  function _renderPreviewHtml(result, opts) {
    opts = opts || {};
    var showSubs = opts.showSubs !== false;
    var showDropped = opts.showDropped !== false;
    var showDots = !!opts.showDots;
    var text = result.raw;
    if (!text) return '<div style="font-size:11px;color:#64748b;padding:8px;text-align:center;">No content to preview.</div>';
    function _esc2(s) {
      return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    }
    // Render whitespace as visible marks when the dots toggle is on.
    // Mirrors Word's "Show formatting marks":
    //   regular space (0x20)        → · (middot)
    //   non-breaking space (0xA0)   → ° (degree mark, distinguishes
    //                                   from regular spaces — common
    //                                   in legal docs between section
    //                                   numbers and titles)
    //   tab (0x09)                  → → (rightward arrow)
    // Applied post-escape so the inserted spans don't get re-escaped.
    // Color #64748b at 80% opacity = visible without competing with
    // body text.
    function _dotify(s) {
      if (!showDots) return s;
      return s
        .replace(/ /g, '<span style="color:#64748b;opacity:0.7;">·</span>')
        .replace(/ /g, '<span style="color:#64748b;opacity:0.7;">°</span>')
        .replace(/\t/g, '<span style="color:#64748b;opacity:0.7;">→</span>');
    }
    var charMeta = result.outputCharMeta || [];
    var paraInfos = result.paraInfos || [];

    // Mark positions for spans/chips. For each output position, track:
    //   isKeyOpen, isUnsubOpen, chipsAt
    var keyOpenAt = {}, keyCloseAt = {}, keySpanByPos = {};
    var unsubOpenAt = {}, unsubCloseAt = {}, unsubSpanByPos = {};
    var chipsAt = {};
    if (showSubs) {
      result.spans.forEach(function (s) {
        if (s.kind !== "key") return;
        keyOpenAt[s.start] = true; keySpanByPos[s.start] = s;
        keyCloseAt[s.end] = true;
      });
    }
    (result.unsubbedSpans || []).forEach(function (s) {
      unsubOpenAt[s.start] = true; unsubSpanByPos[s.start] = s;
      unsubCloseAt[s.end] = true;
    });
    if (showDropped && result.droppedAt) {
      Object.keys(result.droppedAt).forEach(function (k) {
        chipsAt[parseInt(k, 10)] = result.droppedAt[k];
      });
    }

    // ALIGNMENT MAP. Word's `jc` values → CSS text-align. "both" is
    // Word for justified.
    function _alignToCss(a) {
      if (a === "center")  return "center";
      if (a === "right")   return "right";
      if (a === "both" || a === "justify" || a === "distribute") return "justify";
      return "left";
    }
    // Indent comes in twips (twentieths of a point). 20 twips = 1pt
    // ≈ 1.33px. Convert to px for CSS, dropping anything below 8px
    // (rounding noise from list-bullet indents we don't want to render).
    function _indentToPx(twips) {
      if (!twips || twips < 0) return 0;
      var px = Math.round(twips * 1.33 / 20);
      return px >= 8 ? px : 0;
    }
    // Heading-style detection. Word's built-in heading styles render
    // bigger + bolder.
    function _styleClassCss(style) {
      if (!style) return "";
      var s = String(style).toLowerCase();
      if (/heading\s*1|^title$/.test(s)) return "font-size:15px;font-weight:800;margin-top:8px;";
      if (/heading\s*2/.test(s))         return "font-size:14px;font-weight:700;margin-top:6px;";
      if (/heading\s*[3-9]/.test(s))     return "font-size:13px;font-weight:700;margin-top:4px;";
      return "";
    }

    // Walk through the output, building HTML paragraph-by-paragraph.
    // Within each paragraph, group consecutive chars sharing the same
    // formatting (bold/italic/underline) AND the same in-span state
    // (key/unsubbed) into a single <span>. This avoids per-char span
    // bloat while keeping nesting valid.
    var out = "";
    var paraOpen = false;
    var curRunChars = [];
    var curRunStyle = "";
    var curRunClasses = "";
    var curRunTitle = "";

    function _styleFor(meta, inKey, inUnsub, keySpan, unsubSpan) {
      var parts = [];
      if (meta && meta.bold)      parts.push("font-weight:700");
      if (meta && meta.italic)    parts.push("font-style:italic");
      if (meta && meta.underline) parts.push("text-decoration:underline");
      // KEY-substituted text — amber tint that layers on top of inline
      // formatting (so a bold substituted value renders bold + amber).
      if (inKey) {
        parts.push("background:#fef3c7");
        parts.push("color:#92400e");
      }
      // Unsubbed wins visually — red, monospace, bordered. Override
      // bold/italic so it always reads as "fix me".
      if (inUnsub) {
        parts.push("background:#fee2e2");
        parts.push("color:#991b1b");
        parts.push("border:1px solid #fca5a5");
        parts.push("font-weight:700");
        parts.push("font-family:monospace");
        parts.push("font-size:11px");
        parts.push("padding:0 3px");
        parts.push("cursor:pointer");
      }
      return parts.join(";");
    }
    function _attrsFor(inKey, inUnsub, keySpan, unsubSpan) {
      var attrs = "";
      var title = "";
      if (inKey && keySpan) title = "Substituted from " + keySpan.source;
      if (inUnsub && unsubSpan) {
        title = "Click to jump to this tag in the doc + see DEF choices for '" + unsubSpan.key + "'";
        attrs += ' data-bdtt-unsub-key="' + _esc2(unsubSpan.key) + '"';
        attrs += ' data-bdtt-unsub-raw="' + _esc2(unsubSpan.raw) + '"';
        // Source paragraph index — used by the click handler to do a
        // paragraph-scoped Word search instead of body-wide. Massively
        // more reliable for templates with duplicate tag text.
        if (typeof unsubSpan.paraIdx === "number") {
          attrs += ' data-bdtt-unsub-para="' + unsubSpan.paraIdx + '"';
        }
      }
      if (title) attrs += ' title="' + _esc2(title) + '"';
      return attrs;
    }
    function _flushRun() {
      if (!curRunChars.length) return;
      var content = _dotify(_esc2(curRunChars.join("")));
      if (curRunStyle || curRunClasses) {
        out += '<span' + curRunClasses + ' style="' + curRunStyle + '">' + content + '</span>';
      } else {
        out += content;
      }
      curRunChars = [];
    }

    var inKey = false, inUnsub = false;
    var openKeySpan = null, openUnsubSpan = null;
    // Find the source-paragraph index for the FIRST char of each
    // output paragraph so we can apply alignment/indent at <p> open.
    var i = 0, len = text.length;
    // Track the SOURCE paragraph index (in paraInfos / original
    // richParagraphs). Each separator carries its own paraIdx (the
    // paragraph it ENDS), so the next paragraph in the output is at
    // paraIdx + 1. This handles two tricky cases:
    //
    //   1. Empty paragraphs (user pressed Enter in Word → empty <w:p>
    //      with no runs → two separators back-to-back in fullText).
    //      Each separator advances paraIdx, the empty paragraph in
    //      between still gets its own <p>...¶</p>.
    //
    //   2. IF-killed paragraphs (whole paragraphs removed from output
    //      because they were in a losing branch). The kill removes
    //      both content AND separator, so paraIdx jumps over them in
    //      the output. Using the separator's own paraIdx (rather than
    //      a plain counter) keeps source-paragraph-index correct so
    //      formatting (alignment, indent, heading style) lands on the
    //      RIGHT paragraph.
    function _initParaIdx() {
      for (var k = 0; k < charMeta.length; k++) {
        if (!charMeta[k]) continue;
        if (charMeta[k].separator) return charMeta[k].paraIdx;
        return charMeta[k].paraIdx;
      }
      return 0;
    }
    var curParaIdx = _initParaIdx();
    // Sequential index of the OUTPUT paragraph being opened — diff
    // logic uses it to flag which `<p>` elements just changed since
    // the previous render.
    var outputParaIdx = 0;
    function _openParaWithInfo(pi) {
      pi = pi || { alignment: "left", indent: 0, style: null };
      var styleParts = [
        "margin:0 0 6px 0",
        "line-height:1.55",
        "font-size:12px",
        "color:#0f172a",
        "text-align:" + _alignToCss(pi.alignment),
      ];
      var leftPx = _indentToPx(pi.indent);
      if (leftPx) styleParts.push("margin-left:" + leftPx + "px");
      var styleStr = _styleClassCss(pi.style);
      if (styleStr) styleParts.push(styleStr);
      out += '<p data-bdtt-out-idx="' + outputParaIdx + '" style="' + styleParts.join(";") + ';">';
      outputParaIdx++;
      paraOpen = true;
    }
    function _closePara() {
      if (!paraOpen) return;
      _flushRun();
      // ¶ marker — light gray, small, end-of-paragraph affordance.
      out += '<span style="color:#cbd5e1;font-size:10px;margin-left:2px;" title="paragraph break">¶</span></p>';
      paraOpen = false;
    }

    _openParaWithInfo(paraInfos[curParaIdx]);
    while (i < len) {
      // Handle events at this position FIRST (close before open).
      if (keyCloseAt[i])   { _flushRun(); inKey = false; openKeySpan = null; }
      if (unsubCloseAt[i]) { _flushRun(); inUnsub = false; openUnsubSpan = null; }
      if (keyOpenAt[i])    { _flushRun(); inKey = true; openKeySpan = keySpanByPos[i]; }
      if (unsubOpenAt[i])  { _flushRun(); inUnsub = true; openUnsubSpan = unsubSpanByPos[i]; }
      if (chipsAt[i]) {
        _flushRun();
        var alts = chipsAt[i];
        var altList = alts.map(function (a) { return "• " + a.rawTag; }).join("\n");
        out += '<span style="display:inline-block;font-size:9px;font-weight:700;color:#475569;background:#f1f5f9;border:1px solid #cbd5e1;padding:0 4px;margin:0 2px;cursor:help;vertical-align:middle;" title="' + _esc2(alts.length + " alternative branch" + (alts.length === 1 ? "" : "es") + " dropped here:\n" + altList) + '">⊘' + alts.length + '</span>';
      }

      var ch = text.charAt(i);
      var meta = charMeta[i] || {};
      if (meta.separator) {
        // Close current paragraph, advance to next. Use the
        // separator's own paraIdx + 1 to derive the next source
        // paragraph (instead of a plain counter) — this handles both
        // empty paragraphs AND IF-killed paragraphs correctly.
        _closePara();
        i++;
        curParaIdx = meta.paraIdx + 1;
        if (curParaIdx < paraInfos.length) {
          _openParaWithInfo(paraInfos[curParaIdx]);
        }
        continue;
      }
      var newStyle = _styleFor(meta, inKey, inUnsub, openKeySpan, openUnsubSpan);
      var newClasses = _attrsFor(inKey, inUnsub, openKeySpan, openUnsubSpan);
      if (newStyle !== curRunStyle || newClasses !== curRunClasses) {
        _flushRun();
        curRunStyle = newStyle;
        curRunClasses = newClasses;
      }
      curRunChars.push(ch);
      i++;
    }
    if (keyCloseAt[len])   { _flushRun(); inKey = false; }
    if (unsubCloseAt[len]) { _flushRun(); inUnsub = false; }
    _closePara();
    return out;
  }

  function _renderPreviewTab(body) {
    body.innerHTML =
      // First-load big button. Replaced with compact button row in the
      // controls strip after first read.
      '<div id="_bdtt_preview_first_load_wrap">' +
        '<button id="_bdtt_preview_load_big" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;">📥 Read Current Doc</button>' +
      '</div>' +
      '<div id="_bdtt_preview_inputs"></div>' +
      // Compact controls row — Re-read, Temp Save, Apply, toggle-answers,
      // toggles, stats. Hidden until first read.
      '<div id="_bdtt_preview_controls" style="display:none;gap:6px;align-items:center;font-size:10px;flex-wrap:wrap;">' +
        '<button id="_bdtt_preview_reread" type="button" title="Re-read the doc — pulls in any Word edits" style="padding:5px 9px;font-size:10px;font-weight:700;background:#f1f5f9;border:1px solid #cbd5e1;color:#0f172a;cursor:pointer;">🔄 Re-read</button>' +
        '<button id="_bdtt_preview_tempsave" type="button" title="Temp Save Draft for the active test (same as the Test tab button)" style="padding:5px 9px;font-size:10px;font-weight:700;background:#f1f5f9;border:1px solid #cbd5e1;color:#0f172a;cursor:pointer;">💾 Temp Save</button>' +
        '<button id="_bdtt_preview_apply" type="button" title="Re-run the preview engine with current answers (does NOT touch the live doc)" style="padding:5px 9px;font-size:10px;font-weight:700;background:linear-gradient(135deg,#1e3a8a,#1565c0);border:1px solid #1e3a8a;color:#fff;cursor:pointer;">⚡ Apply to Preview</button>' +
        '<button id="_bdtt_preview_toggle_answers" type="button" title="Show / hide the answers grid" style="padding:5px 9px;font-size:10px;font-weight:700;background:#f1f5f9;border:1px solid #cbd5e1;color:#0f172a;cursor:pointer;">' + (_bdttPreviewAnswersOpen ? "▼ Answers" : "▶ Answers") + '</button>' +
        '<button id="_bdtt_preview_pressure" type="button" title="Try EVERY combination of choice DEFs and surface tags that never resolve" style="padding:5px 9px;font-size:10px;font-weight:700;background:#fef3c7;border:1px solid #fcd34d;color:#92400e;cursor:pointer;">🔥 Pressure Test</button>' +
        '<label style="display:flex;align-items:center;gap:4px;cursor:pointer;">' +
          '<input type="checkbox" id="_bdtt_prev_subs" ' + (_bdttPreviewShowSubs ? "checked" : "") + ' /> subs' +
        '</label>' +
        '<label style="display:flex;align-items:center;gap:4px;cursor:pointer;">' +
          '<input type="checkbox" id="_bdtt_prev_dropped" ' + (_bdttPreviewShowDropped ? "checked" : "") + ' /> ⊘ chips' +
        '</label>' +
        '<label style="display:flex;align-items:center;gap:4px;cursor:pointer;" title="Show space dots like Word\'s formatting marks">' +
          '<input type="checkbox" id="_bdtt_prev_dots" ' + (_bdttPreviewShowDots ? "checked" : "") + ' /> · dots' +
        '</label>' +
        '<span id="_bdtt_preview_stats" style="margin-left:auto;color:#64748b;"></span>' +
      '</div>' +
      '<div id="_bdtt_preview_result" style="border:1px solid #cbd5e1;background:#fff;padding:14px 16px;height:65vh;min-height:300px;resize:vertical;overflow:auto;font-family:Georgia,serif;line-height:1.55;"></div>';

