    if (loadBtn) loadBtn.onclick = _onPreviewLoad;

    if (_bdttPreviewParagraphs) {
      _renderPreviewInputsAndResult();
    } else {
      document.getElementById("_bdtt_preview_result").innerHTML =
        '<div style="font-size:11px;color:#64748b;text-align:center;padding:8px;">Click <strong>Read Current Doc</strong> to load paragraphs and start previewing.</div>';
    }
  }

  function _onPreviewLoad() {
    var bigBtn  = document.getElementById("_bdtt_preview_load_big");
    var reBtn   = document.getElementById("_bdtt_preview_reread");
    if (bigBtn) { bigBtn.disabled = true; bigBtn.textContent = "⏳ Reading…"; }
    if (reBtn)  { reBtn.disabled  = true; reBtn.textContent  = "⏳ Re-reading…"; }
    _capturePreviewSource().then(function (paras) {
      _bdttPreviewParagraphs = paras || [];
      // Clear the diff baseline — a Re-read captures fresh content,
      // and we don't want every paragraph to flash "just changed".
      _bdttPreviewLastOutput = null;
      var defs = [];
      var seenNames = {};
      var tagRe = /\{\{([^{}]+)\}\}/g;
      // Track the IF/ELSEIF/ELSE/ENDIF stack as we walk tags so each
      // DEF can record its parent conditions — the chain of IFs that
      // must be true for it to appear in the rendered doc. This is
      // what the user means by "nested": a DEF inside a parent IF
      // only matters when that parent's choice is selected.
      var blockStack = [];
      _bdttPreviewParagraphs.forEach(function (p) {
        var paraText = (typeof p === "string") ? p : (p && p.text) || "";
        var m;
        tagRe.lastIndex = 0;
        while ((m = tagRe.exec(paraText)) !== null) {
          var inner = m[1].trim();
          if (inner.indexOf("IF:") === 0) {
            blockStack.push(inner.substring(3).trim());
            continue;
          }
          if (inner.indexOf("ELSEIF:") === 0) {
            if (blockStack.length) { blockStack.pop(); blockStack.push(inner.substring(7).trim()); }
            continue;
          }
          if (inner.indexOf("ELSE") === 0 && inner.indexOf("ELSEIF:") !== 0) {
            if (blockStack.length) { blockStack.pop(); blockStack.push("true"); }
            continue;
          }
          if (inner.indexOf("ENDIF") === 0) {
            if (blockStack.length) blockStack.pop();
            continue;
          }
          if (inner.indexOf("DEF:") !== 0) continue;
          var d = _parseDefTag(m[0]);
          if (!d || seenNames[d.name]) continue;
          // Snapshot the current IF stack — these are the conditions
          // that gate this DEF's relevance.
          d.parentConditions = blockStack.slice();
          seenNames[d.name] = true;
          defs.push(d);
        }
      });
      // DEFs are pushed in doc-walk order — keep that order in the
      // UI so the user sees questions appear top-to-bottom matching
      // the template's natural flow. Alphabetical sort was breaking
      // the parent → nested-child grouping.
      _bdttPreviewDefs = defs;
      // Hide the big load button once we have content — the compact
      // Re-read button in the controls row takes its place.
      var firstLoadWrap = document.getElementById("_bdtt_preview_first_load_wrap");
      if (firstLoadWrap) firstLoadWrap.style.display = "none";
      _renderPreviewInputsAndResult();
    }).catch(function (err) {
      eli.log.event("tool", "bd_template_tester_preview_capture_failed", { msg: err && err.message });
      _toast("Preview capture failed: " + (err && err.message), "err");
    }).finally(function () {
      if (bigBtn) { bigBtn.disabled = false; bigBtn.textContent = "📥 Read Current Doc"; }
      if (reBtn)  { reBtn.disabled  = false; reBtn.textContent  = "🔄 Re-read"; }
    });
  }

  function _renderPreviewInputsAndResult() {
    var inputsEl = document.getElementById("_bdtt_preview_inputs");
    var controlsEl = document.getElementById("_bdtt_preview_controls");
    if (!inputsEl) return;
    var defs = _bdttPreviewDefs || [];
    if (!defs.length) {
      inputsEl.innerHTML = '<div style="font-size:11px;color:#64748b;font-style:italic;padding:4px 0;">No <code>{{DEF}}</code> tags found in this doc.</div>';
      controlsEl.style.display = "flex";
      _wirePreviewControls();
      _paintPreviewResult();
      return;
    }
    // Pre-populate defaults so dropdowns visibly applied → preview
    // reflects them. Only fills DEFs with VALID defaults (default is
    // one of the choice options), skips text DEFs, skips slots the
    // user already touched. Tags with no DEF or no valid default
    // still appear unanswered → render red. To force-see red for a
    // pre-populated DEF, pick "(no answer)" in its dropdown.
    defs.forEach(function (d) {
      if (_bdttPreviewAnswers[d.name] !== undefined) return;
      if (d.isText) return;
      if (!d.defaultValue) return;
      if (d.options.indexOf(d.defaultValue) === -1) return;
      _bdttPreviewAnswers[d.name] = d.defaultValue;
    });

    // 2-column grid for answer inputs. Each cell stacks its label +
    // input vertically. On very narrow overlays the second column
    // wraps under the first — covered by `minmax(0, 1fr)`. The whole
    // grid collapses behind the clickable ANSWERS (N) heading; the
    // Re-read / Apply / toggle controls stay visible underneath
    // either way.
    var openChev = _bdttPreviewAnswersOpen ? "▼" : "▶";
    // Single-column rows (label + input side-by-side) so nested DEFs
    // can indent under their parents without column-flow weirdness.
    // Each row's indent reflects parentConditions.length × 14px.
    // Inactive nested DEFs (parent condition currently not satisfied)
    // get red label + red border + 60% opacity to telegraph "won't
    // appear in the output right now."
    function _evalCondLocal(condStr, answers) {
      if (condStr === "true") return true;
      var op = condStr.indexOf("!=") !== -1 ? "!=" : (condStr.indexOf("==") !== -1 ? "==" : null);
      if (!op) return false;
      var parts = condStr.split(op);
      if (parts.length < 2) return false;
      var k = parts[0].trim();
      var rhs = parts[1].split("||").map(function (x) { return x.trim().replace(/['"]/g, ""); });
      var actual = answers[k];
      if (actual === undefined || actual === null || actual === "") return false;
      return op === "==" ? rhs.indexOf(String(actual)) !== -1
                         : rhs.indexOf(String(actual)) === -1;
    }
    function _isDefActive(d, answers) {
      if (!d.parentConditions || !d.parentConditions.length) return true;
      return d.parentConditions.every(function (c) { return _evalCondLocal(c, answers); });
    }
    var html = '<div id="_bdtt_preview_answers_header" style="display:flex;align-items:center;gap:6px;cursor:pointer;padding:2px 0 2px;user-select:none;" title="Click to ' + (_bdttPreviewAnswersOpen ? "hide" : "show") + ' answers">' +
        '<span id="_bdtt_preview_answers_chev" style="font-size:9px;color:#64748b;">' + openChev + '</span>' +
        '<span style="font-size:10px;font-weight:700;color:#475569;letter-spacing:0.04em;">ANSWERS (' + defs.length + ')</span>' +
      '</div>' +
      '<div id="_bdtt_preview_answers_grid" style="display:' + (_bdttPreviewAnswersOpen ? "flex" : "none") + ';flex-direction:column;gap:2px;">';
    defs.forEach(function (d) {
      var current = _bdttPreviewAnswers[d.name];
      if (current === undefined) current = d.defaultValue || "";
      var level = (d.parentConditions && d.parentConditions.length) || 0;
      var active = _isDefActive(d, _bdttPreviewAnswers);
      var indentPx = level * 14;
      var labelColor   = active ? "#475569" : "#dc2626";
      var inputBorder  = active ? "#cbd5e1" : "#fca5a5";
      var inputBg      = active ? "#fff"    : "#fef2f2";
      var rowOpacity   = active ? "1"       : "0.75";
      var labelTooltip = d.name;
      if (d.parentConditions && d.parentConditions.length) {
        labelTooltip += "\n\nNested — only appears when:\n" + d.parentConditions.map(function (c) { return c === "true" ? "(ELSE branch)" : c; }).join("\n");
        if (!active) labelTooltip += "\n\n⚠ Parent condition NOT currently satisfied — this question won't affect the output right now.";
      }
      var nestedConnector = level > 0
        ? '<span style="color:#94a3b8;font-size:10px;flex-shrink:0;font-family:inherit;">↳</span>'
        : '';
      html += '<div style="display:flex;align-items:center;gap:6px;padding:1px 0;padding-left:' + indentPx + 'px;opacity:' + rowOpacity + ';">' +
        nestedConnector +
        '<label style="font-size:9px;color:' + labelColor + ';font-weight:600;font-family:monospace;flex:0 0 38%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:1.2;cursor:help;" title="' + _esc(labelTooltip) + '">' + _esc(d.name) + '</label>';
      if (d.isText) {
        html += '<input data-bdtt-prev-input="' + _esc(d.name) + '" type="text" value="' + _esc(current) + '" placeholder="' + _esc(d.defaultValue || "") + '" style="flex:1;padding:3px 6px;font-size:10px;font-family:inherit;border:1px solid ' + inputBorder + ';border-radius:0;background:' + inputBg + ';min-width:0;line-height:1.3;" />';
      } else {
        html += '<select data-bdtt-prev-input="' + _esc(d.name) + '" style="flex:1;padding:3px 6px;font-size:10px;font-family:inherit;border:1px solid ' + inputBorder + ';border-radius:0;background:' + inputBg + ';min-width:0;line-height:1.3;">';
        html += '<option value="">(no answer)</option>';
        d.options.forEach(function (o) {
          var sel = (o === current) ? ' selected' : '';
          html += '<option value="' + _esc(o) + '"' + sel + '>' + _esc(o) + '</option>';
        });
        html += '</select>';
      }
      html += '</div>';
    });
    html += '</div>';
    inputsEl.innerHTML = html;
    controlsEl.style.display = "flex";

    // Wire inputs. Two-handler split:
    //   • oninput  → only repaint the result pane. Fires per keystroke
    //                on text DEFs; keeps typing snappy.
    //   • onchange → full grid + result rebuild so nested DEFs'
    //                active/inactive state updates (red/dim flips
    //                when parent picks satisfy / unsatisfy nested
    //                conditions). Focus + caret restored on the same
    //                input so the user doesn't lose their place.
    inputsEl.querySelectorAll("[data-bdtt-prev-input]").forEach(function (el) {
      var name = el.getAttribute("data-bdtt-prev-input");
      el.oninput = function () {
        _bdttPreviewAnswers[name] = el.value;
        _paintPreviewResult();
      };
      el.onchange = function () {
        _bdttPreviewAnswers[name] = el.value;
        var caretStart = null;
        if (el.setSelectionRange) {
          try { caretStart = el.selectionStart; } catch (_) {}
        }
        _renderPreviewInputsAndResult();
        var sel = '[data-bdtt-prev-input="' + name.replace(/"/g, '\\"') + '"]';
        var newEl = document.querySelector(sel);
        if (newEl) {
          newEl.focus();
          if (caretStart !== null && newEl.setSelectionRange) {
            try { newEl.setSelectionRange(caretStart, caretStart); } catch (_) {}
          }
        }
      };
    });
    // Wire the ANSWERS (N) header — clicking collapses/expands the grid.
    // Direct DOM manipulation (no re-render) so the input values, focus,
    // and scroll position stay intact.
    var hdrEl = document.getElementById("_bdtt_preview_answers_header");
    if (hdrEl) hdrEl.onclick = function () {
      _bdttPreviewAnswersOpen = !_bdttPreviewAnswersOpen;
      var grid = document.getElementById("_bdtt_preview_answers_grid");
      var chev = document.getElementById("_bdtt_preview_answers_chev");
      if (grid) grid.style.display = _bdttPreviewAnswersOpen ? "grid" : "none";
      if (chev) chev.textContent = _bdttPreviewAnswersOpen ? "▼" : "▶";
      hdrEl.title = "Click to " + (_bdttPreviewAnswersOpen ? "hide" : "show") + " answers";
    };
    _wirePreviewControls();
    _paintPreviewResult();
  }

  // Wire the compact controls row (Re-read, Temp Save, Apply, toggle-
  // answers, format checkboxes). Pulled out so the "no DEFs found"
  // branch can also call it.
  function _wirePreviewControls() {
    var subsCb = document.getElementById("_bdtt_prev_subs");
    if (subsCb) subsCb.onchange = function () { _bdttPreviewShowSubs = subsCb.checked; _paintPreviewResult(); };
    var dropCb = document.getElementById("_bdtt_prev_dropped");
    if (dropCb) dropCb.onchange = function () { _bdttPreviewShowDropped = dropCb.checked; _paintPreviewResult(); };
    var dotsCb = document.getElementById("_bdtt_prev_dots");
    if (dotsCb) dotsCb.onchange = function () { _bdttPreviewShowDots = dotsCb.checked; _paintPreviewResult(); };
    var reBtn = document.getElementById("_bdtt_preview_reread");
    if (reBtn) reBtn.onclick = _onPreviewLoad;
    var applyBtn = document.getElementById("_bdtt_preview_apply");
    if (applyBtn) applyBtn.onclick = _onPreviewApply;
    var tempSaveBtn = document.getElementById("_bdtt_preview_tempsave");
    if (tempSaveBtn) tempSaveBtn.onclick = _onTempSave;
    var pressureBtn = document.getElementById("_bdtt_preview_pressure");
    if (pressureBtn) pressureBtn.onclick = _runPressureTest;
    var toggleAnsBtn = document.getElementById("_bdtt_preview_toggle_answers");
    if (toggleAnsBtn) toggleAnsBtn.onclick = function () {
      _bdttPreviewAnswersOpen = !_bdttPreviewAnswersOpen;
      var grid = document.getElementById("_bdtt_preview_answers_grid");
      var chev = document.getElementById("_bdtt_preview_answers_chev");
      var hdr  = document.getElementById("_bdtt_preview_answers_header");
      if (grid) grid.style.display = _bdttPreviewAnswersOpen ? "grid" : "none";
      if (chev) chev.textContent = _bdttPreviewAnswersOpen ? "▼" : "▶";
      if (hdr)  hdr.title = "Click to " + (_bdttPreviewAnswersOpen ? "hide" : "show") + " answers";
      toggleAnsBtn.textContent = _bdttPreviewAnswersOpen ? "▼ Answers" : "▶ Answers";
    };
  }

  // Pressure test — enumerate the cartesian product of every choice
  // DEF's options, run the dry-run engine against each combo, and
  // surface every tag that fails to resolve in one or more combos.
  //
  // Two categories of result:
  //   • "always unresolved" — tag stays raw in EVERY combination.
  //     Usually means the tag's KEY has no matching DEF (orphan), or
  //     a DEF with no usable default. These are real template bugs.
  //   • "sometimes unresolved" — tag resolves in some combos but not
  //     others. Almost always a nested DEF that's only defined inside
  //     a parent IF branch — that branch is taken in some combos
  //     (resolves) but not others (leaves the tag raw because the DEF
  //     was deleted with its losing parent).
  //
  // Combo cap: 5000. Bigger templates with many DEFs would explode
  // (3^N grows fast). The cap surfaces a warning; user can iterate
  // by manually narrowing.
  function _runPressureTest() {
    if (!_bdttPreviewParagraphs) { _toast("Read the doc first.", "warn"); return; }
    var defs = _bdttPreviewDefs || [];
    var choiceDefs = defs.filter(function (d) { return !d.isText && d.options && d.options.length > 0; });
    if (!choiceDefs.length) { _toast("No choice DEFs to test combinations of.", "warn"); return; }
    // Build cartesian product. Each entry is an answers map.
    var combos = [{}];
    for (var ci = 0; ci < choiceDefs.length; ci++) {
      var d = choiceDefs[ci];
      var next = [];
      combos.forEach(function (acc) {
        d.options.forEach(function (o) {
          var nc = {};
          Object.keys(acc).forEach(function (k) { nc[k] = acc[k]; });
          nc[d.name] = o;
          next.push(nc);
        });
      });
      combos = next;
      if (combos.length > 5000) break;
    }
    var capped = false;
    if (combos.length > 5000) { capped = true; combos = combos.slice(0, 5000); }
    var totalCombos = combos.length;
    _toast("⏳ Running " + totalCombos + " combination" + (totalCombos === 1 ? "" : "s") + "…", "info");
    // Run async so the UI thread breathes. Batch of 200 combos per
    // tick → progress visible, no jank.
    var tagCounts = {};       // raw → count of combos where it stayed raw
    var tagSampleKeys = {};   // raw → sample failure key
    var processed = 0;
    var batchSize = 200;
    function _runBatch() {
      var end = Math.min(processed + batchSize, totalCombos);
      for (var bi = processed; bi < end; bi++) {
        var result = _runDryRunPreview(_bdttPreviewParagraphs, combos[bi], {});
        (result.unsubbedSpans || []).forEach(function (s) {
          tagCounts[s.raw] = (tagCounts[s.raw] || 0) + 1;
          if (!tagSampleKeys[s.raw]) tagSampleKeys[s.raw] = s.key;
        });
      }
      processed = end;
      if (processed < totalCombos) {
        setTimeout(_runBatch, 0);
      } else {
        var always = [], sometimes = [];
        Object.keys(tagCounts).forEach(function (raw) {
          var entry = { raw: raw, key: tagSampleKeys[raw], count: tagCounts[raw] };
          if (tagCounts[raw] >= totalCombos) always.push(entry);
          else sometimes.push(entry);
        });
        always.sort(function (a, b) { return String(a.key).localeCompare(String(b.key)); });
        sometimes.sort(function (a, b) { return b.count - a.count; });
        _showPressureTestResults(totalCombos, always, sometimes, capped);
      }
    }
    _runBatch();
  }

  function _showPressureTestResults(totalCombos, always, sometimes, capped) {
    var panelId = "_bdtt_pressure_panel";
    var existing = document.getElementById(panelId);
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
    if (!always.length && !sometimes.length) {
      _toast("✅ Pressure test passed — every tag resolves in every combination tested.", "ok");
      return;
    }
    function _esc2(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
    var panel = document.createElement("div");
    panel.id = panelId;
    panel.style.cssText = [
      "position:fixed",
      "top:50%", "left:50%", "transform:translate(-50%, -50%)",
      "width:min(560px, calc(100vw - 40px))",
      "max-height:80vh",
      "z-index:99999",
      "background:#fff",
      "border:1px solid #cbd5e1",
      "box-shadow:0 12px 36px rgba(15,23,42,0.32)",
      "font-family:Inter,'Segoe UI',system-ui,sans-serif",
      "display:flex", "flex-direction:column",
    ].join(";") + ";";
    function _section(title, items, headerBg, headerFg, blurb) {
      if (!items.length) return "";
      return '<div style="display:flex;flex-direction:column;gap:6px;margin-top:10px;">' +
        '<div style="font-size:10px;font-weight:900;color:' + headerFg + ';background:' + headerBg + ';padding:4px 8px;letter-spacing:0.06em;">' + title + ' (' + items.length + ')</div>' +
        '<div style="font-size:10px;color:#475569;line-height:1.4;padding:0 4px;">' + blurb + '</div>' +
        '<div style="display:flex;flex-direction:column;gap:3px;max-height:240px;overflow-y:auto;">' +
          items.map(function (it) {
            var pct = Math.round((it.count / totalCombos) * 100);
            return '<div style="display:flex;align-items:center;gap:6px;font-size:10px;padding:3px 6px;border:1px solid #e2e8f0;background:#fff;">' +
              '<code style="flex:1;font-family:monospace;color:#0f172a;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + _esc2(it.raw) + '">' + _esc2(it.raw) + '</code>' +
              '<span style="font-size:9px;color:#64748b;flex-shrink:0;">' + it.count + " / " + totalCombos + ' (' + pct + '%)</span>' +
              '<button data-bdtt-pt-jump="' + _esc2(it.raw) + '" type="button" title="Find in doc" style="padding:1px 5px;font-size:10px;background:#fff;border:1px solid #cbd5e1;color:#1565c0;cursor:pointer;flex-shrink:0;">🔎</button>' +
            '</div>';
          }).join("") +
        '</div>' +
      '</div>';
    }
    panel.innerHTML =
      '<div style="padding:10px 14px;background:linear-gradient(135deg,#1e3a8a,#1565c0);color:#fff;display:flex;align-items:center;justify-content:space-between;gap:8px;">' +
        '<div style="display:flex;align-items:center;gap:8px;">' +
          '<span style="font-size:14px;">🔥</span>' +
          '<span style="font-size:13px;font-weight:800;letter-spacing:0.02em;">Pressure Test Result</span>' +
          '<span style="font-size:10px;opacity:0.85;">· ' + totalCombos + ' combo' + (totalCombos === 1 ? '' : 's') + ' tested' + (capped ? ' (capped)' : '') + '</span>' +
        '</div>' +
        '<button id="_bdtt_pt_close" type="button" style="background:rgba(255,255,255,0.18);border:1px solid rgba(255,255,255,0.4);color:#fff;padding:3px 9px;font-size:11px;font-weight:700;cursor:pointer;">✕</button>' +
      '</div>' +
      '<div style="padding:12px;overflow-y:auto;flex:1 1 auto;">' +
        _section("⚠ NEVER resolves", always, "#fee2e2", "#991b1b",
          "These tags stayed raw in every combo. Usually the KEY has no matching DEF, or its DEF has no usable default. Fix in the source template.") +
        _section("⚠ Sometimes unresolved", sometimes, "#fef3c7", "#92400e",
          "These tags resolve in some combos but not others. Typically nested DEFs that only get defined inside a specific parent branch — when the OTHER branch is taken, the DEF (and its substitution) is dropped.") +
      '</div>';
    document.body.appendChild(panel);
    document.getElementById("_bdtt_pt_close").onclick = function () {
      if (panel.parentNode) panel.parentNode.removeChild(panel);
    };
    panel.querySelectorAll("[data-bdtt-pt-jump]").forEach(function (btn) {
      btn.onclick = function () {
        _onFindInDoc(btn.getAttribute("data-bdtt-pt-jump"));
      };
    });
  }

  // Refresh the preview output. The live doc is NOT touched — this
  // just re-runs the JS dry-run engine against the current answers
  // and re-paints the result pane. Functionally similar to the
  // live-update on input change, but exposed as an explicit button
  // for users who want a "commit" action.
  function _onPreviewApply() {
    if (!_bdttPreviewParagraphs) {
      _toast("Read the doc first.", "warn");
      return;
    }
    _paintPreviewResult();
    _toast("✅ Preview refreshed", "ok");
  }

  function _paintPreviewResult() {
    var resEl = document.getElementById("_bdtt_preview_result");
    var statsEl = document.getElementById("_bdtt_preview_stats");
    if (!resEl) return;
    if (!_bdttPreviewParagraphs) {
      resEl.innerHTML = '<div style="font-size:11px;color:#64748b;text-align:center;padding:8px;">Click <strong>Read Current Doc</strong> to load paragraphs.</div>';
      return;
    }
    // Inject the flash-changed CSS keyframes once. Animation fires
    // when a paragraph gets the .bdtt-just-changed class — light
    // yellow background fading to transparent over 2.5s.
    if (!document.getElementById("_bdtt_changed_anim")) {
      var s = document.createElement("style");
      s.id = "_bdtt_changed_anim";
      s.textContent =
        "@keyframes _bdtt_changed_fade {" +
          "0%   { background: #fef3c7; }" +
          "100% { background: transparent; }" +
        "}" +
        ".bdtt-just-changed { animation: _bdtt_changed_fade 2.5s ease-out; }";
      document.head.appendChild(s);
    }
    var result = _runDryRunPreview(_bdttPreviewParagraphs, _bdttPreviewAnswers, {});
    resEl.innerHTML = _renderPreviewHtml(result, {
      showSubs: _bdttPreviewShowSubs,
      showDropped: _bdttPreviewShowDropped,
      showDots: _bdttPreviewShowDots,
    });
    // Paragraph-level diff against the previous output. We mark each
    // output paragraph "just-changed" if its text doesn't appear in
    // the previous output's paragraph set. Hash-based comparison
    // (set membership, not positional) so paragraphs that merely
    // shifted positions due to IF-block changes aren't flagged —
    // only genuinely new content gets the flash.
    if (_bdttPreviewLastOutput !== null) {
      var PARA_SEP = result.paraSep;
      var prevSet = {};
      _bdttPreviewLastOutput.split(PARA_SEP).forEach(function (p) {
        prevSet[p] = (prevSet[p] || 0) + 1;
      });
      var curParas = result.raw.split(PARA_SEP);
      curParas.forEach(function (p, i) {
        if (prevSet[p]) {
          prevSet[p]--; // consume one occurrence so duplicates aren't all "unchanged"
        } else {
          var el = resEl.querySelector('[data-bdtt-out-idx="' + i + '"]');
          if (el) el.classList.add("bdtt-just-changed");
        }
      });
    }
    _bdttPreviewLastOutput = result.raw;
    if (statsEl) {
      var bits = [
        result.substitutionCount + " sub" + (result.substitutionCount === 1 ? "" : "s"),
        result.droppedCount + " dropped",
      ];
      if (result.unsubbedCount) {
        bits.push('<span style="color:#991b1b;font-weight:700;">' + result.unsubbedCount + " unanswered</span>");
      }
      statsEl.innerHTML = bits.join(" · ");
    }
    // Delegate clicks on red unsubbed tags: jump to the tag in Word
    // and open a popover with that DEF's choices to copy.
    resEl.onclick = function (e) {
      var span = e.target.closest && e.target.closest("[data-bdtt-unsub-key]");
      if (!span) return;
      var key = span.getAttribute("data-bdtt-unsub-key");
      var raw = span.getAttribute("data-bdtt-unsub-raw");
      var paraAttr = span.getAttribute("data-bdtt-unsub-para");
      var paraIdx = paraAttr ? parseInt(paraAttr, 10) : null;
      _onUnsubbedClick(span, key, raw, paraIdx);
    };
  }

  // Clicked a red {{...}} in the preview: select the tag in the live
  // doc + open a small popover anchored under the span with that DEF's
  // choices. Each choice click copies the value to clipboard so the
  // user can paste into Word (where the tag is now selected, so paste
  // overwrites it).
  // Remember which tag was last clicked. Popover copy buttons use this
  // to do an in-place doc replace (in addition to clipboard copy) so
  // the user doesn't have to manually paste.
  var _bdttUnsubClickedRaw = null;
  var _bdttUnsubClickedParaIdx = null;

  function _onUnsubbedClick(span, key, raw, paraIdx) {
    _bdttUnsubClickedRaw = raw;
    _bdttUnsubClickedParaIdx = paraIdx;
    if (raw) {
      _findInDocAtPara(raw, paraIdx).then(function (found) {
        if (!found) _toast("Couldn't find tag in doc — re-read may be needed.", "warn");
      });
    }
    _closeUnsubPopover();
    var matchedDef = (_bdttPreviewDefs || []).find(function (d) { return d.name === key; });
    _openUnsubPopover(span, matchedDef);
  }

  // Replace the previously-clicked tag in the live doc with the given
  // text. Uses paragraph-scoped search first, then falls back to body-
  // wide. Returns Promise<boolean>: true if the doc was modified.
  function _replaceTagInDoc(rawText, paraIdx, replacement) {
    if (!rawText) return Promise.resolve(false);
    var needle = String(rawText);
    if (needle.length > 250) needle = needle.slice(0, 250);
    return eli.host.runRaw("bd_template_tester:replace_tag", function (context) {
      var paras = context.document.body.paragraphs;
      paras.load("items");
      return context.sync().then(function () {
        function _replaceInBody() {
          var body = context.document.body;
          if (eli.host.helpers && typeof eli.host.helpers.searchWithFallback === "function") {
            return eli.host.helpers.searchWithFallback(body, needle, context).then(function (range) {
              if (!range) return false;
              range.insertText(replacement, Word.InsertLocation.replace);
              return context.sync().then(function () { return true; });
            });
          }
          var s = body.search(needle, { matchCase: true, matchWildcards: false });
          s.load("items");
          return context.sync().then(function () {
            if (s.items.length > 0) {
              s.items[0].insertText(replacement, Word.InsertLocation.replace);
              return context.sync().then(function () { return true; });
            }
            return false;
          });
        }
        if (paraIdx === null || paraIdx === undefined || paraIdx >= paras.items.length) {
          return _replaceInBody();
        }
        var p = paras.items[paraIdx];
        if (eli.host.helpers && typeof eli.host.helpers.searchWithFallback === "function") {
          return eli.host.helpers.searchWithFallback(p, needle, context).then(function (range) {
            if (range) {
              range.insertText(replacement, Word.InsertLocation.replace);
              return context.sync().then(function () { return true; });
            }
            return _replaceInBody();
          });
        }
        var s = p.search(needle, { matchCase: true, matchWildcards: false });
        s.load("items");
        return context.sync().then(function () {
          if (s.items.length > 0) {
            s.items[0].insertText(replacement, Word.InsertLocation.replace);
            return context.sync().then(function () { return true; });
          }
          return _replaceInBody();
        });
      });
    }).catch(function (err) {
      eli.log.event("tool", "bd_template_tester_replace_failed", { msg: err && err.message });
      return false;
    });
  }

  // Paragraph-scoped find. Searches WITHIN paragraph[paraIdx] first;
  // if that misses, falls back to body-wide search.
  function _findInDocAtPara(rawText, paraIdx) {
    if (!rawText) return Promise.resolve(false);
    if (paraIdx === null || paraIdx === undefined) return _findInDoc(rawText);
    var needle = String(rawText);
    if (needle.length > 250) needle = needle.slice(0, 250);
    return eli.host.runRaw("bd_template_tester:find_in_doc_para", function (context) {
      var paras = context.document.body.paragraphs;
      paras.load("items");
      return context.sync().then(function () {
        var fallbackToBody = function () {
          var body = context.document.body;
          if (eli.host.helpers && typeof eli.host.helpers.searchWithFallback === "function") {
            return eli.host.helpers.searchWithFallback(body, needle, context).then(function (range) {
              if (!range) return false;
              range.select();
              return context.sync().then(function () { return true; });
            });
          }
          var s = body.search(needle, { matchCase: true, matchWildcards: false });
          s.load("items");
          return context.sync().then(function () {
            if (s.items.length > 0) {
              s.items[0].select();
              return context.sync().then(function () { return true; });
            }
            return false;
          });
        };
        if (paraIdx >= paras.items.length) return fallbackToBody();
        var p = paras.items[paraIdx];
        if (eli.host.helpers && typeof eli.host.helpers.searchWithFallback === "function") {
          return eli.host.helpers.searchWithFallback(p, needle, context).then(function (range) {
            if (range) {
              range.select();
              return context.sync().then(function () { return true; });
            }
            return fallbackToBody();
          });
        }
        var s = p.search(needle, { matchCase: true, matchWildcards: false });
        s.load("items");
        return context.sync().then(function () {
          if (s.items.length > 0) {
            s.items[0].select();
            return context.sync().then(function () { return true; });
          }
          return fallbackToBody();
        });
      });
    }).catch(function (err) {
      eli.log.event("tool", "bd_template_tester_find_para_failed", { msg: err && err.message });
      return false;
    });
  }

  function _openUnsubPopover(span, def) {
    // Show ALL DEFs in the doc, not just the matched one. The clicked
    // tag's matched DEF (if any) bubbles to the top with a highlight;
    // the user can pick a value from any DEF — useful when the red
    // tag's name doesn't exactly match a DEF (typo, drift) and the
    // user wants to grab the right value from elsewhere.
    var allDefs = (_bdttPreviewDefs || []).slice();
    // Sort: matched DEF first (if present), then alphabetical.
    allDefs.sort(function (a, b) {
      var aMatch = (def && a.name === def.name) ? 0 : 1;
      var bMatch = (def && b.name === def.name) ? 0 : 1;
      if (aMatch !== bMatch) return aMatch - bMatch;
      return String(a.name).localeCompare(String(b.name));
    });

    var rect = span.getBoundingClientRect();
    var pop = document.createElement("div");
    pop.id = "_bdtt_unsub_pop";
    pop.style.cssText = [
      "position:fixed",
      "top:" + Math.max(8, Math.min(window.innerHeight - 200, rect.bottom + 4)) + "px",
      "left:" + Math.max(8, Math.min(window.innerWidth - 380, rect.left)) + "px",
      "z-index:99999",
      "background:#fff",
      "border:1px solid #cbd5e1",
      "box-shadow:0 8px 24px rgba(15,23,42,0.18)",
      "min-width:340px",
      "max-width:380px",
      "max-height:60vh",
      "overflow-y:auto",
      "font-family:Inter,'Segoe UI',system-ui,sans-serif",
      "font-size:11px",
      "display:flex",
      "flex-direction:column",
    ].join(";") + ";";

    var header = '<div style="position:sticky;top:0;background:#fff;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;border-bottom:1px solid #e2e8f0;">' +
      '<div>' +
        '<div style="font-size:9px;font-weight:900;color:#0f172a;letter-spacing:0.06em;text-transform:uppercase;">All DEF Choices</div>' +
        '<div style="font-size:10px;color:#64748b;margin-top:2px;">Click a value to copy. Tag is selected in Word — paste to replace.</div>' +
      '</div>' +
      '<button id="_bdtt_unsub_close" type="button" style="background:transparent;border:none;font-size:16px;line-height:1;cursor:pointer;color:#94a3b8;padding:0 4px;flex-shrink:0;">×</button>' +
    '</div>';

    if (!allDefs.length) {
      pop.innerHTML = header +
        '<div style="padding:12px;font-size:11px;color:#64748b;font-style:italic;text-align:center;">No DEFs in this doc.</div>';
    } else {
      var body = '<div style="padding:8px 12px 10px;display:flex;flex-direction:column;gap:10px;">' +
        allDefs.map(function (d) {
          var isMatched = (def && d.name === def.name);
          var border = isMatched ? "2px solid #f59e0b" : "1px solid #e2e8f0";
          var nameBadge = isMatched ? ' <span style="font-size:8px;font-weight:900;background:#fef3c7;color:#92400e;padding:1px 4px;letter-spacing:0.04em;">MATCHED</span>' : '';
          var nameEsc = _esc(d.name);
          var inner = '<div style="border:' + border + ';padding:6px 8px;background:' + (isMatched ? "#fffbeb" : "#fff") + ';display:flex;flex-direction:column;gap:5px;">' +
            '<div style="font-size:10px;font-family:monospace;color:#1565c0;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + nameEsc + '">' + nameEsc + nameBadge + '</div>' +
            // Variable form button — copies {{NAME}}. Same for all
            // choices in this DEF, so just one button per DEF.
            '<button data-bdtt-unsub-var="' + nameEsc + '" type="button" style="padding:3px 7px;font-size:10px;font-weight:700;background:#dbeafe;color:#1e40af;border:1px solid #93c5fd;cursor:pointer;font-family:monospace;align-self:flex-start;border-radius:0;">📋 {{' + nameEsc + '}}</button>';
          if (d.isText) {
            inner += '<div style="font-size:9px;color:#64748b;font-style:italic;">(text DEF — IF / ELSEIF only apply to choice DEFs)</div>';
          } else if (d.options.length === 0) {
            inner += '<div style="font-size:9px;color:#64748b;font-style:italic;">(no choices listed)</div>';
          } else {
            // Per-choice rows: each choice has IF and ELSEIF buttons.
            inner += '<div style="display:flex;flex-direction:column;gap:2px;">' +
              d.options.map(function (o) {
                var oEsc = _esc(o);
                return '<div style="display:flex;align-items:center;gap:4px;flex-wrap:wrap;">' +
                  '<span style="font-size:10px;font-family:monospace;color:#0f172a;min-width:70px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + oEsc + '">' + oEsc + '</span>' +
                  '<button data-bdtt-unsub-if="' + nameEsc + '" data-bdtt-unsub-val="' + oEsc + '" type="button" title="Copy {{IF: ' + nameEsc + ' == ' + oEsc + '}}" style="padding:2px 6px;font-size:9px;font-weight:700;background:#dcfce7;color:#166534;border:1px solid #86efac;cursor:pointer;font-family:monospace;border-radius:0;letter-spacing:0.04em;">📋 IF</button>' +
                  '<button data-bdtt-unsub-elseif="' + nameEsc + '" data-bdtt-unsub-val="' + oEsc + '" type="button" title="Copy {{ELSEIF: ' + nameEsc + ' == ' + oEsc + '}}" style="padding:2px 6px;font-size:9px;font-weight:700;background:#fef3c7;color:#92400e;border:1px solid #fcd34d;cursor:pointer;font-family:monospace;border-radius:0;letter-spacing:0.04em;">📋 ELSEIF</button>' +
                '</div>';
              }).join('') +
            '</div>';
          }
          inner += '</div>';
          return inner;
        }).join('') +
      '</div>';
      pop.innerHTML = header + body;
    }
    document.body.appendChild(pop);

    document.getElementById("_bdtt_unsub_close").onclick = _closeUnsubPopover;

    // All three button kinds (Var / IF / ELSEIF) do three things:
    //   1. Copy the formatted text to clipboard (always — fallback if
    //      doc replace fails)
    //   2. If there's a remembered clicked tag, also REPLACE that tag
    //      in the live doc with the formatted text. Saves the user a
    //      Ctrl+V step.
    //   3. After successful replace, clear the remembered tag so a
    //      subsequent click on another button doesn't try to replace
    //      a tag that's already been overwritten.
    function _wireCopyAndReplace(btn, kind, formatter) {
      btn.onclick = function () {
        var name = btn.getAttribute("data-bdtt-unsub-" + kind) || "";
        var v = btn.getAttribute("data-bdtt-unsub-val") || "";
        var snippet = formatter(name, v);
        _copyText(snippet, kind, name);
        if (_bdttUnsubClickedRaw) {
          var raw = _bdttUnsubClickedRaw;
          var paraIdx = _bdttUnsubClickedParaIdx;
          // Clear immediately so concurrent clicks don't double-fire
          _bdttUnsubClickedRaw = null;
          _bdttUnsubClickedParaIdx = null;
          _replaceTagInDoc(raw, paraIdx, snippet).then(function (replaced) {
            if (replaced) {
              _toast("✏️ Replaced in doc with " + snippet, "ok");
            } else {
              // Couldn't find original tag — restore clicked state so
              // a subsequent button click can retry.
              _bdttUnsubClickedRaw = raw;
              _bdttUnsubClickedParaIdx = paraIdx;
            }
          });
        }
      };
    }
    pop.querySelectorAll("[data-bdtt-unsub-var]").forEach(function (btn) {
      _wireCopyAndReplace(btn, "var", function (name) { return "{{" + name + "}}"; });
    });
    pop.querySelectorAll("[data-bdtt-unsub-if]").forEach(function (btn) {
      _wireCopyAndReplace(btn, "if", function (name, v) { return "{{IF: " + name + " == " + v + "}}"; });
    });
    pop.querySelectorAll("[data-bdtt-unsub-elseif]").forEach(function (btn) {
      _wireCopyAndReplace(btn, "elseif", function (name, v) { return "{{ELSEIF: " + name + " == " + v + "}}"; });
    });

    setTimeout(function () {
      document.addEventListener("click", _outsideUnsubClick, true);
    }, 50);
  }

  function _outsideUnsubClick(e) {
    var pop = document.getElementById("_bdtt_unsub_pop");
    if (!pop) return;
    if (pop.contains(e.target)) return;
    _closeUnsubPopover();
  }

  function _closeUnsubPopover() {
    var pop = document.getElementById("_bdtt_unsub_pop");
    if (pop && pop.parentNode) pop.parentNode.removeChild(pop);
    document.removeEventListener("click", _outsideUnsubClick, true);
    _bdttUnsubClickedRaw = null;
    _bdttUnsubClickedParaIdx = null;
  }

  // ─── Bottom toggle button — manual on/off ─────────────────────────
  // Always visible until user explicitly dismisses it. No DOM watchers,
  // no auto-hide on navigation. Visibility persists across reloads via
  // the kernel "config" store. To bring back after dismissing: click the
  // tile in the dashboard.
  //
  // Why manual: an auto-show/hide watcher needs MutationObserver on a
  // wide scope (the kernel replaces _eli3_dashboard_root on _goHome, so
  // anything bound to it goes stale) — which means firing on every
  // taskpane DOM mutation. Even rAF-coalesced, that's avoidable overhead
  // when the user is happy clicking a tile to restore.
  var TOGGLE_ID = "_bdtt_toggle_btn";
  var BTN_VIS_KEY = "bd_template_tester_btn_visible";

  function _loadBtnVisible() {
    // Default true — first install shows the button so user knows the
    // tool installed. Subsequent reads honor whatever the user picked.
    return eli.storage.get("config", BTN_VIS_KEY).then(function (row) {
      if (!row) return true;
      return row.value !== false;
    }).catch(function () { return true; });
  }
  function _saveBtnVisible(v) {
    return eli.storage.put("config", { key: BTN_VIS_KEY, value: !!v })
      .catch(function (e) {
        eli.log.event("tool", "bd_template_tester_btn_vis_put_failed", { msg: e && e.message });
      });
  }

  function _injectToggleButton() {
    if (document.getElementById(TOGGLE_ID)) return;
    var btn = document.createElement("button");
    btn.id = TOGGLE_ID;
    btn.type = "button";
    btn.title = "Open Template Tester (× to dismiss)";
    btn.style.cssText = [
      "position:fixed",
      "bottom:42px",
      "right:18px",
      // Below .eli-overlay (z-index 9999) so any dialog covers the
      // button visually.
      "z-index:9000",
      "padding:8px 14px 8px 14px",
      "font-size:11px",
      "font-weight:800",
      "letter-spacing:0.08em",
      "text-transform:uppercase",
      "color:#fff",
      "background:linear-gradient(135deg,#1e3a8a,#1565c0)",
      "border:1px solid #1e3a8a",
      "border-radius:0",
      "cursor:pointer",
      "box-shadow:0 4px 14px rgba(15,23,42,0.32)",
      "font-family:Inter,'Segoe UI',system-ui,sans-serif",
      "display:inline-flex",
      "align-items:center",
      "gap:10px",
    ].join(";") + ";";
    // Label span + dismiss × in one button — clicking the × hides the
    // button without opening the overlay.
    var label = document.createElement("span");
    label.textContent = "🧪 Test";
    var dismiss = document.createElement("span");
    dismiss.id = "_bdtt_dismiss";
    dismiss.textContent = "×";
    dismiss.title = "Hide button (click the dashboard tile to restore)";
    dismiss.style.cssText = [
      "display:inline-flex",
      "align-items:center",
      "justify-content:center",
      "width:16px",
      "height:16px",
      "font-size:16px",
      "font-weight:700",
      "line-height:1",
      "opacity:0.7",
      "border-left:1px solid rgba(255,255,255,0.25)",
      "padding-left:8px",
      "margin-left:-2px",
    ].join(";") + ";";
    btn.appendChild(label);
    btn.appendChild(dismiss);
    btn.onclick = function (e) {
      // Dismiss × → hide + persist. Don't open the overlay in this case.
      if (e.target && e.target.id === "_bdtt_dismiss") {
        e.stopPropagation();
        _hideToggleButton();
        _saveBtnVisible(false);
        _toast("Test button hidden. Click the Template Tester tile to bring it back.", "info");
        return;
      }
      // Main click → open/close overlay.
      if (document.getElementById("_bdtt_overlay")) _closeOverlay();
      else _openOverlay();
    };
    document.body.appendChild(btn);
    // If a Step 1 render is currently in flight (button was just
    // restored mid-render), re-apply the pulsing state immediately so
    // the user doesn't miss the indicator.
    if (_bdttStep1State === "rendering") _setToggleRenderingState(true);
  }
  function _hideToggleButton() {
    var btn = document.getElementById(TOGGLE_ID);
    if (btn && btn.parentNode) btn.parentNode.removeChild(btn);
  }

  // Inject a global @keyframes block ONCE so the test button can pulse
  // even when the overlay isn't mounted. Document-scoped, so it stays
  // valid across overlay open/close cycles.
  (function _injectPulseKeyframes() {
    if (document.getElementById("_bdtt_global_pulse")) return;
    var s = document.createElement("style");
    s.id = "_bdtt_global_pulse";
    s.textContent =
      "@keyframes _bdtt_pulse_btn {" +
        "0%,100% { background: linear-gradient(135deg, #f59e0b, #d97706); }" +
        "50%     { background: linear-gradient(135deg, #d97706, #b45309); }" +
      "}";
    document.head.appendChild(s);
  })();

  // Flip the floating test button into "rendering" state — amber
  // pulsing background, label swaps to "⏳ Rendering". Visible no
  // matter what panel the user is currently looking at (Step 1 form,
  // dashboard, another tool), as long as the button hasn't been
  // dismissed. Off again when Step 1 completes or fails.
  function _setToggleRenderingState(on) {
    var btn = document.getElementById(TOGGLE_ID);
    if (!btn) return;
    var label = btn.firstElementChild;
    if (on) {
      btn.style.background = "linear-gradient(135deg,#f59e0b,#d97706)";
      btn.style.borderColor = "#b45309";
      btn.style.animation = "_bdtt_pulse_btn 1.4s ease-in-out infinite";
      btn.title = "Build Draft is rendering — wait before clicking anything";
      if (label) label.textContent = "⏳ Rendering";
    } else {
      btn.style.background = "linear-gradient(135deg,#1e3a8a,#1565c0)";
      btn.style.borderColor = "#1e3a8a";
      btn.style.animation = "";
      btn.title = "Open Template Tester (× to dismiss)";
      if (label) label.textContent = "🧪 Test";
    }
  }

  // Initial paint — read persisted state once, inject if visible. No
  // ongoing watchers from here on.
  //
  // Auto-opens the overlay on every load (user explicitly asked: "it
  // should automatically show the dialog until you click test"). The
  // Test button toggles closed; no need to remember per-session "was
  // it dismissed", because dismissing the BUTTON is a separate persist
  // via the × on the button itself.
  _loadBtnVisible().then(function (visible) {
    if (!visible) return;
    _injectToggleButton();
    // Small delay so the kernel finishes its boot-time paint before
    // we layer a draggable overlay on top — avoids a flash where the
    // overlay appears mid-dashboard-mount.
    setTimeout(function () {
      if (document.getElementById(TOGGLE_ID) && !document.getElementById("_bdtt_overlay")) {
        _openOverlay();
      }
    }, 300);
  });

  // ─── Tile click ───────────────────────────────────────────────────
  // Single canonical "restore + open" path. Whether the button was
  // hidden or not, clicking the tile re-shows it AND opens the overlay.
  // This is the documented way to bring the button back after dismiss.
  eli.register({
    tile: {
      app_bd_template_tester: function () {
        _saveBtnVisible(true);
        _injectToggleButton();
        _openOverlay();
      },
    },
  });

  // ─── Build Draft Step 1 lifecycle listeners ───────────────────────
  // Three events from build_draft:
  //   • build_draft:step1_start  → substitution is starting, doc is
  //                                about to mutate. Show "rendering"
  //                                indicator.
  //   • build_draft:step1_done   → substitution finished, doc is
  //                                settled. Show "done + snapshot" CTA.
  //   • build_draft:step1_failed → chain aborted. Clear the indicator
  //                                so the spinner doesn't hang.
  // Each handler re-renders the overlay if it's currently showing the
  // Test tab so the banner updates immediately. If the overlay isn't
  // open, state still updates and shows on next open.
  function _onStep1Event(state, payload) {
    _bdttStep1State = state;
    _bdttLastStep1 = {
      ts: (payload && payload.ts) || Date.now(),
      fieldCount: (payload && payload.fieldCount) || 0,
      msg: payload && payload.msg,
    };
    if (document.getElementById("_bdtt_overlay") && _bdttTab === "test") {
      _renderOverlayBody();
    }
  }
  try {
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("build_draft:step1_start", function (p) {
        _onStep1Event("rendering", p);
        // Also flip the floating test button into "rendering" mode so
        // the user sees the indicator even when the overlay is
        // closed — which is the common case during Step 1 (build_draft
        // is the foreground panel, not the overlay).
        _setToggleRenderingState(true);
      });
      eli.bus.on("build_draft:step1_done", function () {
        _bdttStep1State = null;
        _bdttLastStep1 = null;
        _setToggleRenderingState(false);
        if (document.getElementById("_bdtt_overlay") && _bdttTab === "test") {
          _renderOverlayBody();
        }
      });
      eli.bus.on("build_draft:step1_failed", function (p) {
        _bdttStep1State = null;
        _bdttLastStep1 = null;
        _setToggleRenderingState(false);
        var msg = (p && p.msg) ? p.msg : "unknown";
        _toast("Step 1 failed: " + msg, "err");
        if (document.getElementById("_bdtt_overlay") && _bdttTab === "test") {
          _renderOverlayBody();
        }
      });
    }
  } catch (_step1SubErr) { /* tolerate — listener can rewire on next reload */ }

  eli.log.event("tool", "bd_template_tester_initialized", { email: userEmail });
}
